using System.Runtime.InteropServices;
using ReviveOS.Core;
namespace ReviveOS.WiFiManager;
public record Radio(Guid InterfaceId,string Description,uint Phy,uint Software,uint Hardware);
public static class NativeWifi {
 [DllImport("wlanapi.dll")]static extern uint WlanOpenHandle(uint version,IntPtr reserved,out uint negotiated,out IntPtr handle);
 [DllImport("wlanapi.dll")]static extern uint WlanCloseHandle(IntPtr handle,IntPtr reserved);
 [DllImport("wlanapi.dll")]static extern uint WlanEnumInterfaces(IntPtr handle,IntPtr reserved,out IntPtr list);
 [DllImport("wlanapi.dll")]static extern void WlanFreeMemory(IntPtr p);
 [DllImport("wlanapi.dll")]static extern uint WlanQueryInterface(IntPtr handle,ref Guid guid,int opcode,IntPtr reserved,out uint size,out IntPtr data,out int type);
 [DllImport("wlanapi.dll")]static extern uint WlanSetInterface(IntPtr handle,ref Guid guid,int opcode,uint size,ref PhyState state,IntPtr reserved);
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct InterfaceInfo {public Guid Id;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=256)]public string Description;public int State;}
 [StructLayout(LayoutKind.Sequential)]struct PhyState {public uint Index;public uint Software;public uint Hardware;}
 static void Check(uint error){if(error!=0)throw new System.ComponentModel.Win32Exception((int)error);}
 static IntPtr Open(){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException();Check(WlanOpenHandle(2,IntPtr.Zero,out _,out var h));return h;}
 public static List<Radio> Inspect(){var h=Open();try{return Read(h);}finally{WlanCloseHandle(h,IntPtr.Zero);}}
 static List<Radio> Read(IntPtr h){Check(WlanEnumInterfaces(h,IntPtr.Zero,out var list));try{var result=new List<Radio>();var count=Marshal.ReadInt32(list);if(count<0||count>128)throw new IOException("Lista WLAN inválida");for(int i=0;i<count;i++){var info=Marshal.PtrToStructure<InterfaceInfo>(IntPtr.Add(list,8+i*Marshal.SizeOf<InterfaceInfo>()));var guid=info.Id;Check(WlanQueryInterface(h,ref guid,4,IntPtr.Zero,out var size,out var data,out _));try{var n=Marshal.ReadInt32(data);if(n<0||n>64||size<4+n*12)throw new IOException("Estado WLAN inválido");for(int j=0;j<n;j++){var p=Marshal.PtrToStructure<PhyState>(IntPtr.Add(data,4+j*12));result.Add(new(guid,info.Description,p.Index,p.Software,p.Hardware));}}finally{WlanFreeMemory(data);}}return result;}finally{WlanFreeMemory(list);}}
 public static List<Radio> EnableSoftwareRadio(){var h=Open();try{var states=Read(h);if(states.Count==0)throw new IOException("Nenhum rádio WLAN encontrado");if(states.Any(x=>x.Hardware!=1))throw new InvalidOperationException("Rádio bloqueado por hardware/firmware ou estado desconhecido; use controle físico/OEM. Nenhuma alteração aplicada.");if(states.Any(x=>x.Software is not (1 or 2)))throw new IOException("Estado de software desconhecido; nenhuma mudança aplicada");var backup=Path.Combine(State.Root,"wifi-radio-before.json");if(states.Any(x=>x.Software!=1)&&!File.Exists(backup))State.Save(backup,states);foreach(var radio in states.Where(x=>x.Software!=1)){var g=radio.InterfaceId;var p=new PhyState{Index=radio.Phy,Software=1,Hardware=radio.Hardware};Check(WlanSetInterface(h,ref g,4,12,ref p,IntPtr.Zero));}var after=Read(h);if(after.Any(x=>x.Software!=1||x.Hardware!=1))throw new IOException("Rádio ainda não habilitado");return after;}finally{WlanCloseHandle(h,IntPtr.Zero);}}
 public static void RestoreSoftwareRadio(){var path=Path.Combine(State.Root,"wifi-radio-before.json");if(!File.Exists(path))return;var states=System.Text.Json.JsonSerializer.Deserialize<List<Radio>>(File.ReadAllText(path))??throw new IOException("Backup Wi-Fi inválido");var h=Open();try{foreach(var radio in states){if(radio.Software is not (1 or 2))throw new IOException("Estado salvo inválido");var guid=radio.InterfaceId;var p=new PhyState{Index=radio.Phy,Software=radio.Software,Hardware=radio.Hardware};Check(WlanSetInterface(h,ref guid,4,12,ref p,IntPtr.Zero));}var current=Read(h);if(states.Any(x=>!current.Any(y=>y.InterfaceId==x.InterfaceId&&y.Phy==x.Phy&&y.Software==x.Software)))throw new IOException("Não foi possível validar restauração do rádio");File.Delete(path);}finally{WlanCloseHandle(h,IntPtr.Zero);}}
 public static async Task RecoverBounded(){var attempts=new List<object>();for(int i=1;i<=3;i++){try{var state=EnableSoftwareRadio();attempts.Add(new{Attempt=i,Utc=DateTime.UtcNow,State=state,Error=(string?)null});break;}catch(Exception e){attempts.Add(new{Attempt=i,Utc=DateTime.UtcNow,State=new List<Radio>(),Error=e.Message});if(i<3)await Task.Delay(TimeSpan.FromSeconds(5));}}State.Save(Path.Combine(State.Root,"wifi-last-attempt.json"),attempts);}
 public static Task<string> SetLoginTask(bool enable,string executable){
  if(!Path.IsPathFullyQualified(executable)||executable.Contains('\''))throw new ArgumentException("Caminho inválido");
  var script=enable?$"if(Get-ScheduledTask -TaskName 'ReviveOS-Wifi-User' -ErrorAction SilentlyContinue){{throw 'Tarefa já existe; remova antes de recriar'}}; $u=[System.Security.Principal.WindowsIdentity]::GetCurrent().Name; $a=New-ScheduledTaskAction -Execute '{executable}' -Argument '--wifi-recover'; $t=New-ScheduledTaskTrigger -AtLogOn -User $u; $p=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Limited; Register-ScheduledTask -TaskName 'ReviveOS-Wifi-User' -Description 'ReviveOS: rádio WLAN software; três tentativas no login' -Action $a -Trigger $t -Principal $p | Out-String":"$t=Get-ScheduledTask -TaskName 'ReviveOS-Wifi-User' -ErrorAction SilentlyContinue; if($t){if($t.Description -ne 'ReviveOS: rádio WLAN software; três tentativas no login'){throw 'Tarefa não pertence ao ReviveOS'}; Unregister-ScheduledTask -TaskName 'ReviveOS-Wifi-User' -Confirm:$false}; 'Tarefa removida'";
  return Commands.CheckedPowerShell(script);
 }
}
